'use strict';
const $=id=>document.getElementById(id);let schools=[],current;
function showDocument(appendix=false){const file=appendix?'docs/ntu-appendix.pdf':`docs/${current.id}.pdf`;const title=appendix?'附錄及表格':current.docTitle;$('doc-name').textContent=title;$('pdf').src='viewer.html?file='+encodeURIComponent(file);$('pdf').title=`國立${current.name} ${title} PDF 預覽`;$('expand').href=file;$('original').href=appendix?'https://exam.aca.ntu.edu.tw/graf/brochure/116/end.pdf':current.pdf;$('common').setAttribute('aria-pressed',String(!appendix));$('appendix').setAttribute('aria-pressed',String(appendix));}
function selectSchool(id){current=schools.find(s=>s.id===id)||schools[0];document.querySelectorAll('.school').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===current.id)));$('category').textContent=`${current.group} / ${current.id.toUpperCase()}`;$('school-name').textContent='國立'+current.name;$('school-meta').textContent=`116 學年度 · 碩士班甄試 · ${current.city}`;$('apply').href=current.apply;$('source').href=current.source;$('ntu-extras').hidden=current.id!=='ntu';$('school-note').textContent=current.id==='ntu'?'台大簡章分冊提供，請一併閱讀共同規定、附錄與報考系所規定。':'報名、繳費與資料上傳請於官方系統辦理；系所可能另有規定，請詳閱簡章。';showDocument();history.replaceState(null,'','#'+current.id);}
$('common').onclick=()=>showDocument(false);$('appendix').onclick=()=>showDocument(true);
fetch('schools.json').then(r=>{if(!r.ok)throw Error('資料讀取失敗');return r.json()}).then(data=>{schools=data;$('schools').replaceChildren();let group='';for(const s of data){if(group!==s.group){group=s.group;const label=document.createElement('div');label.className='group-label';label.textContent=group;$('schools').append(label)}const b=document.createElement('button');b.className='school';b.dataset.id=s.id;b.setAttribute('aria-label',`預覽國立${s.name}招生簡章`);b.innerHTML=`<span class="abbr">${s.id.toUpperCase()}</span><span><span class="name">${s.name}</span><small>${s.city}</small></span><span class="arrow" aria-hidden="true">→</span>`;b.onclick=()=>selectSchool(s.id);$('schools').append(b)}selectSchool(location.hash.slice(1));}).catch(()=>{$('schools').textContent='學校資料暫時無法載入，請重新整理頁面。';});
